// Parse consensus building request
const request = $input.first().json;

// Required fields validation
if (!request.topic || !request.proposal || !request.initiator) {
  return [{
    json: {
      error: 'Missing required fields: topic, proposal, initiator',
      status: 'invalid'
    }
  }];
}

// Create consensus session
const consensusId = `consensus_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
const consensusData = {
  ...request,
  consensus_id: consensusId,
  created_at: new Date().toISOString(),
  status: 'discussion_phase',
  phases: {
    discussion: {
      status: 'active',
      started_at: new Date().toISOString(),
      duration_minutes: request.discussion_minutes || 10
    },
    refinement: {
      status: 'pending',
      duration_minutes: request.refinement_minutes || 5
    },
    final_vote: {
      status: 'pending',
      duration_minutes: request.vote_minutes || 5
    }
  },
  participants: request.participants || ['agent_dungeon_master', 'agent_narrator', 'agent_combat_manager'],
  consensus_threshold: request.consensus_threshold || 0.8,
  current_consensus_level: 0,
  concerns: [],
  suggestions: [],
  iterations: 0,
  max_iterations: request.max_iterations || 3
};

return [{
  json: consensusData
}];

// Start discussion phase
const consensus = $input.first().json;

// Create discussion prompt for all participants
const discussionPrompt = {
  type: 'consensus_discussion',
  consensus_id: consensus.consensus_id,
  topic: consensus.topic,
  proposal: consensus.proposal,
  phase: 'discussion',
  initiator: consensus.initiator,
  deadline: new Date(Date.now() + consensus.phases.discussion.duration_minutes * 60000).toISOString(),
  instructions: `
CONSENSUS BUILDING DISCUSSION

Topic: ${consensus.topic}

Initial Proposal:
${JSON.stringify(consensus.proposal, null, 2)}

Please provide:
1. Your analysis of the proposal
2. Any concerns or objections
3. Suggestions for improvement
4. Your initial position (support/neutral/oppose)

Discussion ends: ${new Date(Date.now() + consensus.phases.discussion.duration_minutes * 60000).toLocaleString()}
`
};

return consensus.participants.map(participant => ({
  json: {
    ...discussionPrompt,
    to_agent: participant,
    from_agent: 'consensus_builder'
  }
}));

// Store consensus session
const consensus = $input.first().json;

const sessionData = {
  consensus_id: consensus.consensus_id,
  topic: consensus.topic,
  proposal: consensus.proposal,
  initiator: consensus.initiator,
  participants: consensus.participants,
  phases: consensus.phases,
  consensus_threshold: consensus.consensus_threshold,
  status: consensus.status,
  current_consensus_level: consensus.current_consensus_level,
  concerns: consensus.concerns,
  suggestions: consensus.suggestions,
  iterations: consensus.iterations,
  max_iterations: consensus.max_iterations,
  created_at: consensus.created_at
};

return [{
  json: sessionData
}];

// Schedule discussion phase end and analysis
const consensus = $input.first().json;
const discussionDuration = consensus.phases.discussion.duration_minutes || 10;

return [{
  json: {
    consensus_id: consensus.consensus_id,
    action: 'analyze_discussion',
    scheduled_for: new Date(Date.now() + discussionDuration * 60000).toISOString(),
    current_phase: 'discussion',
    next_phase: 'refinement'
  }
}];
